import { test, expect } from "@playwright/experimental-ct-react";
import type { Page } from "@playwright/test";
import { PdfEditor } from "../../src/components/preview/viewers/pdf-editor/PdfEditor";

// 9 A4 pages.
const PDF = "storybook/preview-files/pv_cm.pdf";
// 3 pages, generated by scripts/generate-test-pdfs.mjs.
const OTHER_PDF = "storybook/preview-files/pdf_with_links.pdf";
const WORKER = "/pdf.worker.mjs";

// pdf.js creates a block for every page up front but only draws the pages
// near the visible area: a canvas inside a block means the page was drawn.
const pageCanvas = (page: Page, pageNumber: number) =>
  page.locator(`.page[data-page-number="${pageNumber}"] canvas`);

// Each loaded document runs in its own pdf.js worker, which
// loadingTask.destroy() terminates.
const pdfWorkers = (page: Page) =>
  page.workers().filter((worker) => worker.url().includes("pdf.worker"));

test.describe("PDF Editor", () => {
  test("Renders the pages and the text layer", async ({ mount, page }) => {
    await mount(<PdfEditor src={PDF} pdfWorkerSrc="/pdf.worker.mjs" />);

    await expect(page.locator(".pdfViewer .page")).toHaveCount(9, { timeout: 10000 });
    await expect(page.locator('.page[data-page-number="1"] canvas')).toBeVisible({ timeout: 10000 });
    await expect(
      page.locator(".textLayer").getByText("PROCÈS VERBAL DU CONSEIL MUNICIPAL").first(),
    ).toBeAttached({ timeout: 10000 });
  });

  test("Fits the first page to the container width", async ({
    mount,
    page,
  }) => {
    await mount(<PdfEditor src={PDF} pdfWorkerSrc={WORKER} />);
    await expect(pageCanvas(page, 1)).toBeVisible({ timeout: 10000 });

    // The editor fills the viewport (position: absolute; inset: 0). Without
    // the "page-width" scale, pdf.js draws an A4 page about 800px wide.
    const viewportWidth = page.viewportSize()!.width;
    const firstPage = page.locator('.page[data-page-number="1"]');
    await expect(async () => {
      const box = await firstPage.boundingBox();
      expect(box!.width).toBeGreaterThan(viewportWidth * 0.9);
      expect(box!.width).toBeLessThanOrEqual(viewportWidth);
    }).toPass({ timeout: 10000 });
  });

  test("Draws the content of the first page", async ({ mount, page }) => {
    await mount(<PdfEditor src={PDF} pdfWorkerSrc={WORKER} />);
    const canvas = pageCanvas(page, 1);
    await expect(canvas).toBeVisible({ timeout: 10000 });

    // A visible canvas can still be blank: measure the share of pixels
    // darker than the white page background.
    await expect(async () => {
      const inkRatio = await canvas.evaluate((el: HTMLCanvasElement) => {
        const { data } = el
          .getContext("2d")!
          .getImageData(0, 0, el.width, el.height);
        let ink = 0;
        for (let i = 0; i < data.length; i += 4) {
          const painted = data[i + 3] > 0;
          const dark = data[i] < 200 || data[i + 1] < 200 || data[i + 2] < 200;
          if (painted && dark) ink++;
        }
        return ink / (data.length / 4);
      });
      expect(inkRatio).toBeGreaterThan(0.01);
    }).toPass({ timeout: 10000 });
  });

  test("Draws a later page once it is scrolled into view", async ({
    mount,
    page,
  }) => {
    await mount(<PdfEditor src={PDF} pdfWorkerSrc={WORKER} />);
    await expect(pageCanvas(page, 1)).toBeVisible({ timeout: 10000 });
    await expect(pageCanvas(page, 9)).not.toBeAttached();

    await page.locator('.page[data-page-number="9"]').scrollIntoViewIfNeeded();

    await expect(pageCanvas(page, 9)).toBeVisible({ timeout: 10000 });
  });

  test("Replaces the document when src changes", async ({ mount, page }) => {
    const component = await mount(
      <PdfEditor src={PDF} pdfWorkerSrc={WORKER} />,
    );
    await expect(page.locator(".pdfViewer .page")).toHaveCount(9, {
      timeout: 10000,
    });

    await component.update(<PdfEditor src={OTHER_PDF} pdfWorkerSrc={WORKER} />);

    await expect(page.locator(".pdfViewer .page")).toHaveCount(3, {
      timeout: 10000,
    });
    await expect(
      page.locator(".textLayer").getByText("PDF Links Test").first(),
    ).toBeAttached({ timeout: 10000 });
    await expect(
      page.locator(".textLayer").getByText("PROCÈS VERBAL DU CONSEIL MUNICIPAL"),
    ).toHaveCount(0);

    // The new document is loaded, so its worker exists: a single worker left
    // means the one of the first document was terminated.
    await expect
      .poll(() => pdfWorkers(page).length, { timeout: 10000 })
      .toBe(1);
  });

  test("Terminates the pdf.js worker when unmounted", async ({
    mount,
    page,
  }) => {
    const errors: Error[] = [];
    page.on("pageerror", (error) => errors.push(error));

    const component = await mount(
      <PdfEditor src={PDF} pdfWorkerSrc={WORKER} />,
    );
    await expect(pageCanvas(page, 1)).toBeVisible({ timeout: 10000 });
    expect(pdfWorkers(page)).toHaveLength(1);

    await component.unmount();

    await expect(page.locator(".pdfViewer")).not.toBeAttached();
    await expect
      .poll(() => pdfWorkers(page).length, { timeout: 10000 })
      .toBe(0);
    expect(errors).toEqual([]);
  });
});

